document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("ideal-gas-form"),t=document.getElementById("ideal-gas-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("ig-p").value),a=parseFloat(document.getElementById("ig-v").value),i=parseFloat(document.getElementById("ig-n").value),o=parseFloat(document.getElementById("ig-t").value),d=.0821;if(3!==[!isNaN(n),!isNaN(a),!isNaN(i),!isNaN(o)].filter(Boolean).length)return t.textContent="Enter exactly three parameters.",void 0;isNaN(n)?t.innerHTML=`<b>P =</b> ${(i*d*o/a).toFixed(4)} atm`:isNaN(a)?t.innerHTML=`<b>V =</b> ${(i*d*o/n).toFixed(4)} L`:isNaN(i)?t.innerHTML=`<b>n =</b> ${(n*a/(d*o)).toFixed(4)} mol`:isNaN(o)&&(t.innerHTML=`<b>T =</b> ${(n*a/(i*d)).toFixed(4)} K`)})});